function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  let depth = 0;
  for (const ch of s) {
    if (ch !== '(' && ch !== ')') return "s may contain only '(' and ')'.";
    depth += ch === '(' ? 1 : -1;
    if (depth < 0) return 's must be balanced: a ")" closes nothing.';
  }
  if (depth !== 0) return 's must be balanced: some "(" is never closed.';
  return null;
}

