  const stack = [];
  const result = [];
  for (const ch of s) {
    if (ch === '(') {
      if (stack.length > 0) {
        result.push(ch);
      }
      stack.push(ch);
    } else {
      stack.pop();
      if (stack.length > 0) {
        result.push(ch);
      }
    }
  }
  return result.join('');
}

