function removeOuterParentheses(s) {
  // Repeatedly cut off the shortest non-empty balanced prefix and keep its inside.
  const balanced = (text) => text.split('(').length === text.split(')').length;
  let out = '';
  let rest = s;
  while (rest.length > 0) {
    let end = 2;
    while (!balanced(rest.slice(0, end))) end += 2;
    out += rest.slice(1, end - 1);
    rest = rest.slice(end);
  }
  return out;
}

