function generate(rand, size) {
  const pairs = size === 'large' ? 4000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 10);
  // A per-input bias toward opening gives shallow or deep strings.
  const lean = 0.25 + rand() * 0.5;
  let open = 0, depth = 0, s = '';
  while (s.length < 2 * pairs) {
    if (open < pairs && (depth === 0 || rand() < lean)) { s += '('; open++; depth++; }
    else { s += ')'; depth--; }
  }
  return [s];
}
